assertions:
expect(() =>
      applyEdits(xml, [
        { start: 3, end: 5, value: "a" },
        { start: 4, end: 6, value: "b" },
      ]),
    ).toThrow(expect.objectContaining({ code: "XML_EDIT_OVERLAP" }))

expect(() =>
      applyEdits(xml, [
        { start: xml.indexOf("text"), end: xml.indexOf("text") + 4, value: "<!DOCTYPE x><x/>" },
      ]),
    ).toThrow(expect.objectContaining({ code: "XML_EDIT_UNSAFE" }))

expect(rels.children.map(n => [n.localName, { ...n.attributes }])).toEqual(Array.from({ length: i === 4 ? 2 : 1 }, () => ['Relationship', {
      Id: 'rId1', Type: 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument',
      Target: i < 2 ? 'word/%66oo.xml' : i === 3 ? 'word/missing.xml' : 'word/document.xml',
    }]))
